{
  "tool": "kmp_write_memory",
  "save_as": "constraint",
  "arguments": {
    "about": "example:guide:first-decision",
    "actor": "guide-writer",
    "source_kind": "human",
    "idempotency_key": "guide-first-decision:constraint:v1",
    "labels": {
      "case": [
        "first-decision"
